{"query": {"esql": "// Event volume by OS
// Events per day split by OS. Use the chart toggle for the visualization.
FROM logs-*
| STATS events = COUNT(*) BY day = BUCKET(@timestamp, 1 day), host.os.type
| SORT day"}, "filter": []}

{"query": {"esql": "// Asset inventory
// Hosts and data streams seen in the last 30 days, with event counts and first and last seen.
FROM logs-*
| WHERE @timestamp > NOW() - 30 days
| STATS events = COUNT(*), first_seen = MIN(@timestamp), last_seen = MAX(@timestamp) BY host.name, host.os.type, data_stream.dataset
| SORT host.name, data_stream.dataset"}, "filter": []}
